from pathlib import Path
import json
def build_html(cards,cfg,decks):
 engine=Path('calculator_engine.js').read_text()
 example=next(d for d in decks if d['name']=='Explorers of the Deep')
 exampletext='Commander\n'+'\n'.join(f"{a['count']} {a['name']}" for a in example['entries'] if a['section']=='commander')+'\n\nDeck\n'+'\n'.join(f"{a['count']} {a['name']}" for a in example['entries'] if a['section']=='cards')
 html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Commander Doubles • Points Lab</title>
<style>body{font:16px system-ui;background:#102127;color:#eef5f3;margin:0 auto;padding:30px;max-width:1250px}h1{font-size:30px;margin-bottom:8px}p{color:#bad0d1;line-height:1.5}section{background:#19333a;border:1px solid #35535b;border-radius:12px;padding:20px;margin:20px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px}textarea,input,button{font:inherit;border-radius:6px;border:1px solid #6e969c;padding:10px}textarea{width:100%;box-sizing:border-box;background:#0b1c22;color:#edf5f3;min-height:260px;font:14px monospace}input{background:#0b1c22;color:#edf5f3;max-width:95%}label{display:block;margin:12px 0}button{background:#99d6bc;color:#102127;cursor:pointer;margin:5px}button:hover{background:#bcebd9}.score{font-size:32px;font-weight:700;color:#99d6bc}.warning{color:#ffd39a}table{width:100%;font-size:14px;border-collapse:collapse}td,th{text-align:left;padding:8px;border-bottom:1px solid #35535b}.muted{font-size:13px}details{margin-top:12px}summary{cursor:pointer}@media(max-width:750px){.grid{grid-template-columns:1fr}body{padding:16px}}</style>
<h1>Commander Doubles · Points Lab</h1><p>Fixed individual-card prices. Team total is the sum of two decks; teammate synergy has no surcharge.</p><p class="warning">Provisional model v0.2 • Precon baseline, not a validated bracket detector. A 1,000-point Bracket 3 deck is a design goal. Scores do not authorize banned cards.</p>
<section><label>Team cap <input id="teamcap" type="number" min="0" value="2000"></label><label>Individual cap (0 = disabled) <input id="deckcap" type="number" min="0" value="0"></label><button id="score">Calculate both decks</button><button id="example">Load example in Deck A</button><div id="combined" class="score">Paste decks to begin</div></section>
<div class="grid">'''
 for k in ['a','b']:
  html+=f'''<section><h2>Deck {k.upper()}</h2><label>Commander(s), separated by semicolon<br><input id="cmd{k}" placeholder="Or use a Commander section in the list" style="width:95%"></label><textarea id="list{k}" aria-label="Deck {k.upper()} list" placeholder="Commander&#10;1 Commander name&#10;&#10;Deck&#10;1 Sol Ring&#10;..."></textarea><div id="result{k}"></div></section>'''
 html+='''</div><section><h2>Point overrides</h2><p class="muted">Import a JSON object mapping Oracle IDs or card names to integer points, or a scoring_config.json containing overrides. Overrides affect prices only. Export them before closing; this page keeps changes in memory.</p><input id="import" type="file" accept=".json"><button id="exportOverrides">Export overrides</button><button id="exportReport">Export scored team report</button><div id="overrideStatus"></div></section><p class="muted">Offline Oracle snapshot: 2026-10-19. Includes all downloaded Oracle records; nonlegal records are flagged. Most automatic estimates need human review. Section headers and Moxfield printing suffixes are supported. Sideboards and companions are excluded. Each resolved commander is counted once when also named in its commander input. No external API calls.</p><script>'''
 html+='const CARDS='+json.dumps(cards,ensure_ascii=True).replace('</','<\\/')+';\nconst EXAMPLE='+json.dumps(exampletext)+';\n'+engine
 html+='''
const indexes=makeIndex(CARDS);let overrides={},last=null;const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(k,r){$('result'+k).innerHTML='<p class="score">'+r.total+' '+(r.complete?'points':'known-card subtotal · INCOMPLETE')+'</p><p>'+r.size+' cards · '+r.gameChangers+' Game Changers · '+r.provisionalCards+' provisional card estimates</p><p>Commanders: '+esc(r.commanders.join('; ')||'not identified')+'</p>'+r.warnings.map(w=>'<p class="warning">'+esc(w)+'</p>').join('')+'<details open><summary>Highest point contributions</summary><table><tr><th>Card</th><th>Each</th><th>Total</th></tr>'+r.rows.slice(0,15).map(c=>'<tr><td>'+c.q+' × '+esc(c.n)+(c.override?' [override]':c.reviewed?'':' [provisional]')+'</td><td>'+c.points+'</td><td>'+c.total+'</td></tr>').join('')+'</table></details>';}
function calculate(){const a=scoreDeck($('lista').value,$('cmda').value,indexes,overrides),b=scoreDeck($('listb').value,$('cmdb').value,indexes,overrides);render('a',a);render('b',b);const total=a.total+b.total,cap=Number($('teamcap').value),individual=Number($('deckcap').value);const capValid=Number.isSafeInteger(cap)&&cap>=0&&Number.isSafeInteger(individual)&&individual>=0;const valid=a.complete&&b.complete&&!a.warnings.length&&!b.warnings.length&&capValid;$('combined').textContent=total+' team points'+(!a.complete||!b.complete?' · INCOMPLETE':'')+' · '+(!capValid?'invalid caps':cap&&total>cap?'over team cap':individual&&(a.total>individual||b.total>individual)?'over individual cap':valid?'within configured caps':'review deck warnings');last={modelVersion:'0.2.0-provisional',snapshot:'2026-10-19',a,b,total,teamCap:cap,individualCap:individual,overrides,valid};}
function download(name,value){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('score').onclick=calculate;$('example').onclick=()=>{$('lista').value=EXAMPLE;$('cmda').value='';calculate();};$('import').onchange=async e=>{try{const candidate=validateOverrides(JSON.parse(await e.target.files[0].text()),indexes);overrides=candidate;$('overrideStatus').textContent=Object.keys(overrides).length+' overrides loaded.';calculate();}catch(err){$('overrideStatus').textContent='Import rejected: '+err.message;}};$('exportOverrides').onclick=()=>download('point_overrides.json',overrides);$('exportReport').onclick=()=>{calculate();download('scored_team_report.json',last);};
</script></html>'''
 Path('commander_doubles_calculator.html').write_text(html)
